const inputItems = $input.all();

function decodeHtmlEntities(value) {
  return String(value || '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>');
}

function htmlToPlainText(value) {
  return decodeHtmlEntities(value)
    .replace(/<(br|\/p|\/div|\/li|\/h[1-6])\b[^>]*>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n[ \t]+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function normalizeImageUrl(rawUrl, baseUrl) {
  let url = String(rawUrl || '').trim();
  if (!url || url.startsWith('data:')) return '';

  if (url.includes(',')) url = url.split(',')[0].trim();
  url = url.split(/\s+/)[0];

  try {
    let parsedUrl = new URL(url, baseUrl || undefined);

    if (['tuyensinhtest.test', 'localhost', '127.0.0.1'].includes(parsedUrl.hostname)) {
        if (baseUrl) {
            let baseParsed = new URL(baseUrl);
            parsedUrl.protocol = baseParsed.protocol;
            parsedUrl.hostname = baseParsed.hostname;
            parsedUrl.port = baseParsed.port;
        }
    }
    return parsedUrl.href;
  } catch (error) {
    return url;
  }
}

for (const item of inputItems) {
  const body = item.json.body;
  if (!body || typeof body !== 'object') {
    throw new Error('Webhook thiếu body JSON.');
  }

  if (!body.event_type) {
    throw new Error('Webhook thiếu body.event_type.');
  }

  if (body.event_type === 'lead_became_hot') {
    if (!body.data || typeof body.data !== 'object') throw new Error('lead_became_hot thiếu body.data.');
    if (!String(body.data.sender_id || '').trim()) throw new Error('lead_became_hot thiếu body.data.sender_id.');
    if (!String(body.data.message || '').trim()) throw new Error('lead_became_hot thiếu body.data.message.');
    continue;
  }

  if (body.event_type === 'run_lead_campaign') {
    if (!body.data || typeof body.data !== 'object') throw new Error('run_lead_campaign thiếu body.data.');
    if (!Array.isArray(body.data.recipients) || body.data.recipients.length === 0) throw new Error('run_lead_campaign không có danh sách recipients.');
    if (!String(body.data.message || '').trim()) throw new Error('run_lead_campaign thiếu body.data.message.');
    continue;
  }

  if (!body.data || typeof body.data !== 'object') throw new Error('Webhook thiếu body.data.');

  const d = body.data;
  const htmlContent = d.content || d.noidung || '';
  const fallbackPlainContent = htmlToPlainText(htmlContent);
  d.title = String(d.title || '').trim();
  d.plain_content = String(d.plain_content || fallbackPlainContent)
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n[ \t]+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  if (body.event_type === 'new_article') {
    if (!d.title) throw new Error('Bài viết thiếu body.data.title.');
    if (!d.plain_content) throw new Error('Bài viết thiếu body.data.plain_content và không thể tạo lại từ content.');
  }

  d.auto_publish = [1, true, '1', 'true'].includes(d.auto_publish) ? 1 : 0;

  const baseUrl = d.url || d.thumbnail || '';
  const images = [];
  const imageRegex = /<(?:img|source)\b[^>]*\b(?:src|data-src|data-original|srcset)=["']([^"']+)["']/gi;
  let match;

  while ((match = imageRegex.exec(String(htmlContent))) !== null) {
    const normalized = normalizeImageUrl(match[1], baseUrl);
    if (normalized && !images.includes(normalized)) images.push(normalized);
  }

  if (images.length === 0 && d.thumbnail) {
    const thumbnail = normalizeImageUrl(d.thumbnail, baseUrl);
    if (thumbnail) images.push(thumbnail);
  }

  d.content_images = images;
  d.has_images = images.length > 0;
  d.validation = { plain_content_length: d.plain_content.length, image_count: images.length };
}

return inputItems;

const query = $input.first().json.query || {};
const mode = query.hub_mode || query['hub.mode'];
const verifyToken = query.hub_verify_token || query['hub.verify_token'];
const challenge = query.hub_challenge || query['hub.challenge'];
const expectedToken = 'ctut';
if (mode === 'subscribe' && verifyToken === expectedToken && challenge) {
  return [{ json: { statusCode: 200, responseBody: challenge.toString() } }];
}
return [{ json: { statusCode: 403, responseBody: 'Invalid verify token' } }];

const body = $input.first().json.body || {};

let text = '';
let senderId = '';
let senderName = '';
let interactionType = 'chat';
let isComment = false;
let commentId = '';
let postId = '';

if (body.entry && body.entry[0]) {
  const entry = body.entry[0];

  if (entry.messaging && entry.messaging[0]) {
    const event = entry.messaging[0];

    text = event.message ? event.message.text || '' : '';
    senderId = event.sender ? event.sender.id || '' : '';
    interactionType = 'chat';
  } else if (entry.changes && entry.changes[0]) {
    const change = entry.changes[0];
    const value = change.value || {};

    if (
      change.field === 'feed'
      && value.verb === 'add'
    ) {
      if (value.item === 'comment') {
        interactionType = 'comment';
        text = value.message || '';
        isComment = true;
      } else if (
        value.item === 'like'
        || value.item === 'reaction'
      ) {
        interactionType = 'like';
      } else if (value.item === 'share') {
        interactionType = 'share';
      }

      senderId = value.from ? value.from.id || '' : '';
      senderName = value.from ? value.from.name || '' : '';
      commentId = String(value.comment_id || '').trim();
      postId = String(value.post_id || '').trim();
    }
  }
}

return [
  {
    json: {
      body: {
        event_type: 'incoming_message',
        data: {
          message: text,
          sender_id: senderId,
          sender_name: senderName,
          is_comment: isComment,
          interaction_type: interactionType,
          comment_id: commentId,
          post_id: postId,
          raw_fb: body
        }
      }
    }
  }
];

const items = $input.all();
const token = $env.FB_MESSENGER_TOKEN || '';
if (!token) throw new Error('Thiếu FB_MESSENGER_TOKEN trong môi trường chạy n8n.');
const transformNode = $('Transform FB Message').first();
for (const item of items) {
  const originalData = transformNode ? transformNode.json.body?.data : {};
  const comment_id = originalData?.comment_id || '';
  const messageText = item.json.message || item.json.body?.data?.message || 'Xin lỗi, hệ thống đang bận.';
  if (!comment_id) { item.json.fb_error = 'Thiếu comment_id để gửi trả lời.'; continue; }
  try {
    const response = await this.helpers.httpRequest({ method: 'POST', url: 'https://graph.facebook.com/v26.0/' + comment_id + '/comments', qs: { access_token: token }, body: { message: messageText }, json: true });
    item.json.fb_reply_response = response;
  } catch (err) { item.json.fb_reply_error = err.message; }
}
return items;

