const source = $('Extract AI JSON').item.json;
const r1 = JSON.parse($('AI Duyệt Vòng 1 (Kiểm Tra Sự Thật)').item.json.choices[0].message.content);
const r2 = JSON.parse($('AI Duyệt Vòng 2 (Kiểm Tra Thương Hiệu)').item.json.choices[0].message.content);
const isApprove1 = r1.approved === true || String(r1.approved).toLowerCase() === 'true';
