const items = $input.all();
const output = [];

function fillTemplate(template, data) {
  const name = String(data.full_name || '').trim() || 'bạn';
  const major = String(data.intended_major || '').trim() || 'ngành bạn quan tâm';
  const score = data.score === null || data.score === undefined ? '' : String(data.score);
  return String(template || '').replace(/\{name\}/g, name).replace(/\{major\}/g, major).replace(/\{score\}/g, score).trim();
}

for (const item of items) {
  const body = item.json.body || item.json;
  const eventType = String(body.event_type || '').trim();
  const data = body.data || {};

  if (eventType === 'lead_became_hot') {
    const senderId = String(data.sender_id || '').trim();
    if (!senderId) throw new Error('lead_became_hot thiếu sender_id.');
    output.push({ json: { campaign_id: data.campaign_id || '', campaign_name: data.campaign_name || 'Chăm sóc Hot Lead tự động', campaign_mode: 'auto_hot', lead_id: data.lead_id || null, channel: 'messenger', recipient: senderId, sender_id: senderId, email: '', full_name: data.full_name || '', intended_major: data.intended_major || '', score: data.score ?? null, subject: '', message: fillTemplate(data.message, data) } });
    continue;
  }

  if (eventType === 'run_lead_campaign') {
    const recipients = Array.isArray(data.recipients) ? data.recipients : [];
    for (const recipient of recipients) {
      const channel = String(recipient.channel || '').trim().toLowerCase();
      const email = String(recipient.email || recipient.recipient || '').trim();
      const senderId = String(recipient.sender_id || recipient.recipient || '').trim();
      if (channel === 'email' && !email) continue;
      if (channel === 'messenger' && !senderId) continue;
      if (!['email', 'messenger'].includes(channel)) continue;
      const merged = { ...recipient, campaign_id: data.campaign_id || '', campaign_name: data.campaign_name || '', campaign_mode: data.campaign_mode || 'manual' };
      output.push({ json: { campaign_id: merged.campaign_id, campaign_name: merged.campaign_name, campaign_mode: merged.campaign_mode, lead_id: recipient.lead_id || null, channel, recipient: channel === 'email' ? email : senderId, email: channel === 'email' ? email : '', sender_id: channel === 'messenger' ? senderId : '', full_name: recipient.full_name || '', intended_major: recipient.intended_major || '', score: recipient.score ?? null, subject: fillTemplate(data.subject || '', merged), message: fillTemplate(data.message || '', merged) } });
    }
  }
}

if (!output.length) throw new Error('Không có người nhận hợp lệ sau khi chuẩn hóa chiến dịch.');
return output;

