const items = $input.all();
const token = String($env.FB_PAGE_ACCESS_TOKEN || '').trim();

function bodyOf(response) {
  return response && Object.prototype.hasOwnProperty.call(
    response,
    'body'
  )
    ? response.body
    : response;
}

async function graphRequest(method, path, qs = {}) {
  const response = await this.helpers.httpRequest({
    method,
    url:
      'https://graph.facebook.com/v26.0/'
      + String(path).replace(/^\/+/, ''),
    qs: {
      ...qs,
      access_token: token
    },
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });

  const statusCode = Number(
    response?.statusCode
    || response?.status
    || 0
  );

  const body = bodyOf(response) || {};
  const metaError = body?.error || null;

  if (
    metaError
    || statusCode < 200
    || statusCode >= 300
  ) {
    const error = new Error(
      JSON.stringify(metaError || body)
    );

    error.graphStatusCode = statusCode;
    error.graphBody = body;
    throw error;
  }

  return body;
}

function normalizeError(error) {
  const meta =
    error?.graphBody?.error
    || error?.graphBody
    || null;

  if (meta && typeof meta === 'object') {
    return {
      message: String(meta.message || ''),
      type: String(meta.type || ''),
      code: meta.code ?? null,
      error_subcode: meta.error_subcode ?? null,
      fbtrace_id: String(meta.fbtrace_id || '')
    };
  }

  return {
    message: String(error?.message || 'Không có chi tiết'),
    type: '',
    code: null,
    error_subcode: null,
    fbtrace_id: ''
  };
}

for (const item of items) {
  const commentId = String(
    item.json.comment_id || ''
  ).trim();

  const postId = String(
    item.json.post_id || ''
  ).trim();

  const expectedPageId = String(
    item.json.expected_page_id
    || (
      postId.includes('_')
        ? postId.split('_')[0]
        : ''
    )
  ).trim();

  item.json.facebook_hide_status = 'failed';
  item.json.facebook_hidden = false;
  item.json.facebook_can_hide = null;
  item.json.facebook_hide_error = '';
  item.json.facebook_hide_attempted_at =
    new Date().toISOString();

  if (!token) {
    item.json.facebook_hide_error = JSON.stringify({
      stage: 'configuration',
      message:
        'Thiếu FB_PAGE_ACCESS_TOKEN trong môi trường n8n.'
    });
    continue;
  }

  if (!commentId) {
    item.json.facebook_hide_error = JSON.stringify({
      stage: 'input',
      message:
        'Webhook thiếu comment_id nên không thể ẩn comment.'
    });
    continue;
  }

  let stage = 'xác định Page của token';
  let tokenPageId = '';
  let tokenPageName = '';

  try {
    const page = await graphRequest(
      'GET',
      'me',
      {
        fields: 'id,name'
      }
    );

    tokenPageId = String(page?.id || '');
    tokenPageName = String(page?.name || '');

    item.json.token_page_id = tokenPageId;
    item.json.token_page_name = tokenPageName;

    if (!tokenPageId) {
      throw new Error(
        'Token hợp lệ nhưng /me không trả về Page ID.'
      );
    }

    if (
      expectedPageId
      && tokenPageId !== expectedPageId
    ) {
      throw new Error(
        'Token thuộc Page '
        + tokenPageId
        + ' (' + tokenPageName + ')'
        + ', nhưng bài viết thuộc Page '
        + expectedPageId + '.'
      );
    }

    stage = 'đọc quyền thao tác trên comment';

    const comment = await graphRequest(
      'GET',
      encodeURIComponent(commentId),
      {
        fields:
          'id,message,permalink_url,is_hidden,'
          + 'can_hide,can_remove,from'
      }
    );

    item.json.facebook_can_hide =
      comment?.can_hide ?? null;
    item.json.facebook_is_hidden =
      comment?.is_hidden ?? null;
    item.json.facebook_can_remove =
      comment?.can_remove ?? null;
    item.json.facebook_comment_url =
      String(comment?.permalink_url || '');

    if (comment?.is_hidden === true) {
      item.json.facebook_hide_status = 'hidden';
      item.json.facebook_hidden = true;
      item.json.facebook_hide_error = '';
      item.json.facebook_hide_response = {
        success: true,
        already_hidden: true
      };
      continue;
    }

    if (comment?.can_hide === false) {
      throw new Error(
        'Facebook trả can_hide=false.'
      );
    }

    stage = 'ẩn comment';

    const result = await graphRequest(
      'POST',
      encodeURIComponent(commentId),
      {
        is_hidden: 'true'
      }
    );

    if (result?.success !== true) {
      throw new Error(
        'Meta không trả success=true: '
        + JSON.stringify(result)
      );
    }

    item.json.facebook_hide_status = 'hidden';
    item.json.facebook_hidden = true;
    item.json.facebook_hide_error = '';
    item.json.facebook_hide_response = result;
  } catch (error) {
    const detail = normalizeError(error);

    item.json.facebook_hide_status = 'failed';
    item.json.facebook_hidden = false;
    item.json.facebook_hide_error = JSON.stringify({
      stage,
      comment_id: commentId,
      post_id: postId,
      expected_page_id: expectedPageId,
      token_page_id: tokenPageId,
      token_page_name: tokenPageName,
      ...detail
    });

    /*
     * Không throw.
     * Comment vẫn phải đi tiếp sang Laravel để Admin biết:
     * - nội dung độc hại;
     * - Facebook chưa ẩn được;
     * - nguyên nhân cụ thể từ Meta.
     */
  }
}

return items;

const items = $input.all();
const token = String($env.FB_PAGE_ACCESS_TOKEN || '').trim();

function errorDetail(error) {
  const candidates = [
    error?.response?.data,
    error?.response?.body,
    error?.context?.data,
    error?.cause?.response?.data,
    error?.cause?.response?.body,
    error?.body,
    typeof error?.toJSON === 'function'
      ? error.toJSON()
      : null,
    error?.message
  ];

  const value = candidates.find(
    (candidate) =>
      candidate !== undefined
      && candidate !== null
      && candidate !== ''
  );

  return typeof value === 'string'
    ? value
    : JSON.stringify(value || {});
}

for (const item of items) {
  const postId = String(item.json.post_id || '').trim();
  const expectedPageId = postId.includes('_')
    ? postId.split('_')[0]
    : '';

  item.json.post_message = '';
  item.json.post_url = '';
  item.json.post_created_time = '';
  item.json.expected_page_id = expectedPageId;
  item.json.token_page_id = '';
  item.json.token_page_name = '';
  item.json.facebook_token_mismatch = false;
  item.json.facebook_post_error = '';

  if (!token) {
    item.json.facebook_post_error =
      'n8n chưa có FB_PAGE_ACCESS_TOKEN.';
    continue;
  }

  if (!postId) {
    item.json.facebook_post_error =
      'Webhook Facebook không trả post_id.';
    continue;
  }

  try {
    const page = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://graph.facebook.com/v26.0/me',
      qs: {
        fields: 'id,name',
        access_token: token
      },
      json: true
    });

    item.json.token_page_id = String(page?.id || '');
    item.json.token_page_name = String(page?.name || '');

    if (
      expectedPageId
      && item.json.token_page_id
      && expectedPageId !== item.json.token_page_id
    ) {
      item.json.facebook_token_mismatch = true;
      item.json.facebook_post_error =
        'FB_PAGE_ACCESS_TOKEN thuộc Page '
        + item.json.token_page_id
        + ' (' + item.json.token_page_name + ')'
        + ', nhưng bài viết thuộc Page '
        + expectedPageId + '.';
      continue;
    }

    const post = await this.helpers.httpRequest({
      method: 'GET',
      url:
        'https://graph.facebook.com/v26.0/'
        + encodeURIComponent(postId),
      qs: {
        fields: 'id,message,permalink_url,created_time',
        access_token: token
      },
      json: true
    });

    item.json.post_message = String(post?.message || '');
    item.json.post_url = String(post?.permalink_url || '');
    item.json.post_created_time =
      String(post?.created_time || '');

    if (!item.json.post_url && postId.includes('_')) {
      const parts = postId.split('_');
      item.json.post_url =
        'https://www.facebook.com/'
        + parts[0]
        + '/posts/'
        + parts.slice(1).join('_');
    }
  } catch (error) {
    item.json.facebook_post_error =
      'Không lấy được thông tin bài viết: '
      + errorDetail(error);
  }
}

return items;
